/// Specification function to compute the triangular number of n.
fn triangle(n: u32) -> u32 {
    if n == 0 {
        0
    } else {
        n + triangle(n - 1)
    }
}

/// Proof function to establish that the triangular number function is monotonic.
fn triangle_is_monotonic(i: u32, j: u32) -> bool {
    if i <= j {
        triangle(i) <= triangle(j)
    } else {
        true // If i > j, the statement is vacuously true.
    }
}

/// Tail-recursive function to compute the triangular number using an accumulator.
fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    if idx > n {
        return; // Base case: if the current index exceeds the target, terminate.
    }
    *sum += idx; // Update the accumulator with the current index.
    tail_triangle(n, idx + 1, sum); // Recursive call with the next index.
}

